}

/* 寄語：白色貼文卡、不歪、深色字 */
.nuo-cal-memory .message-letter-paper {
    transform: none !important;
    border-radius: 20px !important;
    border: none !important;
    background-image: none !important;
    box-shadow: var(--ig-shadow) !important;
}

.nuo-cal-memory .message-letter-paper div {
    color: var(--ig-ink) !important;
    font-family: var(--ig-font) !important;
}

.nuo-cal-memory .letter-content,
.nuo-cal-memory .signer-name {
    color: var(--ig-ink);
}

.nuo-cal-memory .envelope-overlay {
    border-radius: 20px !important;
}

/* ================= 底欄：整條暗色列，選中頁籤下方小白點 ================= */
.nuo-cal-nav-btn > svg {
    width: 22px;
    height: 22px;
    stroke-width: 1.9;
}

.nuo-cal-nav-btn span {
    letter-spacing: 0.6px;
}

.nuo-cal-nav-btn.active {
    position: relative;
}

.nuo-cal-nav-btn.active::after {
    content: '';
    position: absolute;
    left: 50%;
    bottom: -6px;
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: var(--ig-onpage);
    transform: translateX(-50%);
}

/* 加號鈕：白色圓角方塊 + 中央灰愛心，右下角一顆黑色小加號 */
.add-button {
    position: relative;
    margin-top: -34px;
    background-size: cover;
    background-position: center;
}

.add-button::before {
    content: '';
    position: absolute;
    inset: 0;
    margin: auto;
    width: 26px;
    height: 26px;
    background: var(--ig-heart);
    -webkit-mask: var(--ig-heart-svg) center / contain no-repeat;
    mask: var(--ig-heart-svg) center / contain no-repeat;
}

.add-button > svg {
    position: absolute;
    right: -6px;
    bottom: -6px;
    width: 12px;
    height: 12px;
    padding: 4px;
    box-sizing: content-box;
    border-radius: 50%;
    background: var(--ig-ink);
    color: #fff;
    stroke-width: 3;
    box-shadow: 0 0 0 2px var(--ig-page);
}

/* ================= 細節收口（照參考圖 4/5）================= */
/* 標題 / 分區標題用襯線展示字（參考圖 5 的 Special day / Check-in） */
.month-title,
.section-title,
.overlap-title-text,
.memory-title,
.report-header,
.stat-name,
.timeline-header-title {
    font-family: var(--ig-serif) !important;
}

/* 今日卡片：條目 emoji 洗成灰階、「Soon」黃字改灰 */
