div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-first .msg-plain-them,
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-single .bubble-them-custom,
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-single .msg-plain-them {
  margin-top: 20px !important;        /* 下压距离 */
}
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-first .bubble-them-custom::before,
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-first .msg-plain-them::before,
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-single .bubble-them-custom::before,
div.chat-detail-screen .msg-bubble-wrapper.msg-them.is-single .msg-plain-them::before {
  content: "구온우" !important;        /* ← 改成你的备注 */
  display: block !important;
  position: absolute !important;
  top: -18px !important;
  left: 4px !important;
  right: auto !important;
  width: auto !important;
  height: auto !important;
  background: none !important;
  font-size: 12.5px !important;
  line-height: 15px !important;
  font-weight: 400 !important;
  color: #4A5560 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
  z-index: 4 !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【06 时间 + 1】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 我方：气泡左下   AI：气泡右下
     1
   10:42
   只在每组最后一条显示；对方回复后 1 消失 */

/* --- 1. 已读勾勾不要 --- */
div.chat-detail-screen:not(#_k) .msg-wa-checks {
  display: none !important;
}

/* --- 2. 时间容器：移出气泡排版，贴在气泡外侧底边 --- */
div.chat-detail-screen:not(#_k) .msg-wa-meta.msg-wa-meta {
  position: absolute !important;
  top: auto !important;
  bottom: calc(-1 * var(--time-drop)) !important;
  display: block !important;
  float: none !important;
  width: max-content !important;
  height: auto !important;
  min-width: 0 !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: normal !important;
  font-size: 10px !important;
  background: none !important;
  border: none !important;
  box-shadow: none !important;
  z-index: 5 !important;
  pointer-events: none !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-me .msg-wa-meta.msg-wa-meta {
  right: calc(100% + var(--time-gap)) !important;
  left: auto !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-them .msg-wa-meta.msg-wa-meta {
  left: calc(100% + var(--time-gap)) !important;
  right: auto !important;
}

/* 连发的第一条、中间几条不显示时间 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper:is(.is-first, .is-mid) .msg-wa-meta {
  display: none !important;
}

/* --- 3. 时间：竖排（1 在上），隐藏「上午 / 下午」只留数字 --- */
div.chat-detail-screen:not(#_k) .msg-wa-meta .msg-wa-time.msg-wa-time {
  position: static !important;
  top: auto !important;
  bottom: auto !important;
  left: auto !important;
  right: auto !important;
  display: flex !important;
  flex-direction: column !important;
  flex-wrap: nowrap !important;
  gap: 0 !important;
  width: max-content !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  float: none !important;
  transform: none !important;
  overflow: hidden !important;
  text-indent: -2em !important;       /* ← 两个汉字的宽度；露出半个「午」就调成 -2.1em */
  white-space: nowrap !important;
  font-size: 11.5px !important;
  line-height: 12px !important;
  color: var(--time-color) !important;
  -webkit-text-fill-color: var(--time-color) !important;
  font-variant-numeric: tabular-nums !important;
  z-index: 5 !important;
  pointer-events: none !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-me .msg-wa-meta .msg-wa-time.msg-wa-time {
  align-items: flex-end !important;
  justify-content: flex-end !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-them .msg-wa-meta .msg-wa-time.msg-wa-time {
  align-items: flex-start !important;
  justify-content: flex-start !important;
}

/* 时间的 ::before 不用 */
div.chat-detail-screen:not(#_k) .msg-wa-time::before {
  content: none !important;
  display: none !important;
}
/* 不在消息里的时间：::after 不显示 */
div.chat-detail-screen .msg-wa-time::after {
  content: none !important;
}

/* --- 4. 1：时间上面一行 --- */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper:is(.msg-me, .msg-them) .msg-wa-time::after {
  content: "1" !important;
  display: block !important;
  position: relative !important;
  order: -1 !important;               /* 排在时间文字前面 = 上面一行 */
  margin: 0 !important;
  padding: 0 !important;
  text-indent: 0 !important;          /* 不跟着时间往左推 */
  font-size: 11px !important;
  font-weight: 700 !important;
  line-height: 11px !important;
  color: var(--unread-color) !important;
  -webkit-text-fill-color: var(--unread-color) !important;
  visibility: visible !important;
  opacity: 1 !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-me .msg-wa-time::after {
  transform: translateX(var(--unread-shift-me)) !important;
}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-them .msg-wa-time::after {
  transform: translateX(calc(-1 * var(--unread-shift-them))) !important;
}

/* --- 5. 后面出现对方的消息 → 1 消失（打字气泡不算） --- */
div.chat-detail-screen:not(#_k) .chat-message-list-custom > *:has(.msg-me):has(~ * .msg-them:not(.nuo-typing-indicator *)) .msg-wa-time::after,
div.chat-detail-screen:not(#_k) .chat-message-list-custom > *:has(.msg-them):has(~ * .msg-me) .msg-wa-time::after {
  content: none !important;
  display: none !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【07 引用】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 给 名字 的留言
   被引用的文字（或缩略图）
   ─────────
   回复内容 */

/* --- 1. 引用块：去旧底色，下方分割线，靠左贴齐 --- */
div.chat-detail-screen .msg-reply-block {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  gap: 3px !important;
  margin: 2px 0 8px 0 !important;
  padding: 0 0 8px 0 !important;
  text-indent: 0 !important;
  background: none !important;
  border: none !important;
  border-left: none !important;
  border-bottom: 1px solid var(--quote-line) !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  min-width: 140px !important;
  overflow: hidden !important;
}
div.chat-detail-screen .msg-reply-block::before,
div.chat-detail-screen .msg-reply-block::after {
  content: none !important;
  display: none !important;
}

/* --- 2. 第一行：给 名字 的留言 --- */
div.chat-detail-screen .msg-reply-block .msg-reply-block-name {
  display: block !important;
  margin: 0 !important;
  padding: 0 !important;
  text-indent: 0 !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  line-height: 18px !important;
  color: var(--quote-name-color) !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  max-width: 100% !important;
}

div.chat-detail-screen .msg-reply-block .msg-reply-block-name::before {
  content: "回复" !important;        /* ← 前缀，后面不带空格 */
  display: inline !important;
  position: static !important;
  width: auto !important;
  margin: 0 2px 0 0 !important;     /* ← 「回复」和名字的距离 */
  padding: 0 !important;
  background: none !important;
}
div.chat-detail-screen .msg-reply-block .msg-reply-block-name::after {
  content: none !important;
}

/* --- 3. 第二行：被引用的文字 --- */
div.chat-detail-screen .msg-reply-block .msg-reply-block-text {
  display: -webkit-box !important;
  -webkit-box-orient: vertical !important;
  -webkit-line-clamp: 1 !important;
  margin: 0 !important;
  font-size: 12px !important;
  font-weight: 400 !important;
  line-height: 18px !important;
  color: var(--quote-text-color) !important;
  overflow: hidden !important;
  white-space: normal !important;
  word-break: break-all !important;
}

/* --- 4. 引用图片 / 表情包 / 视频：小方块 --- */
div.chat-detail-screen .msg-bubble-wrapper .msg-reply-block.msg-reply-block .msg-reply-block-media {
  display: inline-flex !important;
  flex: 0 0 var(--quote-thumb) !important;
  width: var(--quote-thumb) !important;
  height: var(--quote-thumb) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: var(--quote-thumb) !important;
  max-height: var(--quote-thumb) !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  border-radius: 6px !important;
  background: transparent !important;
  line-height: 0 !important;
}
div.chat-detail-screen .msg-bubble-wrapper .msg-reply-block.msg-reply-block :is(img, video) {
  display: block !important;
  position: static !important;
  width: var(--quote-thumb) !important;
  height: var(--quote-thumb) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  max-width: var(--quote-thumb) !important;
  max-height: var(--quote-thumb) !important;
  margin: 0 !important;
  padding: 0 !important;
  object-fit: cover !important;
  border-radius: 6px !important;
  box-shadow: none !important;
  transform: none !important;
}
div.chat-detail-screen .msg-bubble-wrapper .msg-reply-block.msg-reply-block .msg-reply-block-media * {
  max-width: var(--quote-thumb) !important;
  max-height: var(--quote-thumb) !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 我方气泡里的引用：名字换成角色名 */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-me .msg-reply-block .msg-reply-block-name,
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-me .msg-reply-block .msg-reply-block-name > * {
  font-size: 0 !important;
}

div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-me .msg-reply-block .msg-reply-block-name,
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-me .msg-reply-block .msg-reply-block-name > * {
  font-size: 0 !important;
  line-height: 0 !important;     /* ← 新加：被压掉的原名字不再占一行 */
}

div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-me .msg-reply-block .msg-reply-block-name::before {
  content: "回复\2009" var(--char-name) !important;   /* \2009 = 窄空格 */
  display: block !important;                          /* 不跟被压成 0 的原文字共用一行，避免多出高度 */
  margin: 0 !important;
  font-size: 12px !important;
  font-weight: 600 !important;
  line-height: var(--quote-line-h) !important;       /* 原来写死 18px，改成跟变量走 */
}

/* --- 引用块收紧 --- */
:root {
  /* 🐕 */ --quote-row-gap: 0px;      /* 「回复XX」和引用文字之间 */
  /* 🐕 */ --quote-line-h: 15px;      /* 两行的行高 */
  /* 🐕 */ --quote-pad: 4px;          /* 引用文字到分割线 */
  /* 🐕 */ --quote-after: 4px;        /* 分割线到下面的回复文字 */
}

div.chat-detail-screen:not(#_k) .msg-reply-block {
  gap: var(--quote-row-gap) !important;
  padding-bottom: var(--quote-pad) !important;
  margin-bottom: var(--quote-after) !important;
}
div.chat-detail-screen:not(#_k) .msg-reply-block .msg-reply-block-name,
div.chat-detail-screen:not(#_k) .msg-reply-block .msg-reply-block-text,
div.chat-detail-screen:not(#_k) .msg-reply-block .msg-reply-block-name::before {
  line-height: var(--quote-line-h) !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【08 表情包 / 真实图片】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
div.chat-detail-screen .msg-bubble-wrapper [class*="sticker"] img:not(.msg-reply-block *),
div.chat-detail-screen .msg-bubble-wrapper img[class*="sticker"]:not(.msg-reply-block *) {
  display: block !important;
  width: var(--sticker-size) !important;
  height: var(--sticker-size) !important;
  max-width: var(--sticker-size) !important;
  max-height: var(--sticker-size) !important;
  object-fit: contain !important;
  margin: 0 !important;
}
div.chat-detail-screen :is(.msg-image-card, .msg-image-wrapper) img:not(.msg-reply-block *) {
  display: block !important;
  width: auto !important;
  height: auto !important;
  max-width: var(--photo-max-w) !important;
  max-height: var(--photo-max-h) !important;
  min-width: 0 !important;
  min-height: 0 !important;
  object-fit: contain !important;
  border-radius: 10px !important;
}

/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【09 顶栏】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 只作用于聊天窗口顶栏：规则挂在 .chat-header-custom 下，不碰 .glass-header（设定页也用它） */

/* --- 1. 顶栏背景 + 高度，浮在聊天区上方 --- */
div.chat-detail-screen {
  position: relative !important;
}
div.chat-detail-screen .chat-header-custom {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  display: flex !important;
  align-items: center !important;
  box-sizing: border-box !important;
  height: var(--hdr-height) !important;
  min-height: var(--hdr-height) !important;
  padding: var(--hdr-offset) 18px 0 6px !important;
  background: var(--hdr-bg) !important;
