div.chat-detail-screen:not(#_k) .msg-bubble-wrapper {
  z-index: auto !important;
  isolation: auto !important;
  will-change: auto !important;
  animation-fill-mode: none !important;
}
/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【撤回提示 · 纯文字，可点开原文】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* 只去掉胶囊外观，不隐藏子元素、不清零字号
   点开原文的提示和原文都是 App 自己渲染的，藏掉就点不开了 */

/* 行容器：居中，展开后原文排在下面 */
div.chat-detail-screen:not(#_k) .msg-recalled {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  margin: 10px 0 !important;
  background: transparent !important;
}

/* 去掉胶囊，改成纯文字 */
div.chat-detail-screen:not(#_k) .msg-recalled .msg-system {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  padding: 0 !important;
  margin: 0 !important;
  max-width: 75% !important;
  font-size: 12px !important;
  font-style: normal !important;
  font-weight: 400 !important;
  line-height: 1.5 !important;
  color: #6B7685 !important;           /* ← 文字颜色，在蓝灰底上能看清 */
  text-align: center !important;
  white-space: normal !important;
  word-break: break-word !important;
  cursor: pointer !important;
  pointer-events: auto !important;
}

/* 里面的子元素（展开后的原文等）也去掉框和底色，跟着上面的文字样式走 */
div.chat-detail-screen:not(#_k) .msg-recalled .msg-system * {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 0 !important;
  color: inherit !important;
  font-size: inherit !important;
  line-height: inherit !important;
  text-align: center !important;
}

/* 去掉装饰性的伪元素 */
div.chat-detail-screen:not(#_k) .msg-recalled .msg-system::before,
div.chat-detail-screen:not(#_k) .msg-recalled .msg-system::after {
  content: none !important;
  display: none !important;
}
/* ◆◆◆ 补丁 2（替换版）：撤回提示只留一行字 ◆◆◆ */
/* 结构：.msg-system 里直接写着「x撤回一条消息」这行字，「点击查看」是它唯一的子元素
   隐藏全部子元素，只剩那行字，也不响应点击 */

div.chat-detail-screen:not(#_k) .msg-recalled .msg-system {
  position: static !important;
  display: block !important;
  max-width: none !important;
  white-space: nowrap !important;
  text-align: center !important;
  font-size: 12px !important;
  line-height: 1.5 !important;
  color: #6B7685 !important;
  cursor: default !important;
  pointer-events: none !important;
}

/* 「点击查看」以及点开后的原文，全部隐藏 */
div.chat-detail-screen:not(#_k) .msg-recalled .msg-system > * {
  display: none !important;
}
/* ◆◆◆ 补丁 3：撤回提示往上抬 ◆◆◆ */
/* 只改撤回行自己，不碰外层两层无类名容器（清零外层会让消息叠在一起） */
div.chat-detail-screen:not(#_k) .msg-recalled {
  margin-top: -14px !important;        /* ← 往上抬多少，越负越往上 */
  margin-bottom: 4px !important;       /* 和下一条的距离 */
  padding-top: 0 !important;
  padding-bottom: 0 !important;
  min-height: 0 !important;
}
/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【卡片合集：礼物 / 定位 / 名片 / 文件】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
/* ═══════════════════════════════════════════════
   00 变量（定位 / 名片 / 文件）
   01 礼物卡 · Kakao 선물하기
   02 真实位置（提取自屿）
   03 个人名片（提取自屿）
   04 文件卡（提取自屿）
   05 去掉四种卡片外的气泡尾巴
   ═══════════════════════════════════════════════ */

/* ◆◆◆ 【00 变量】 ◆◆◆ */
div.chat-detail-screen:not(#_k) {
  /* 真实位置 */
  --loc-w: 230px;
  --loc-radius: 10px;
  --loc-map-h: 84px;
  --loc-map-img: url("https://i.postimg.cc/hjpMGWm9/E218BFEE-9E47-4E60-BB25-217A96B5FE0F.png");
  --loc-name-color: #1A1A1A;
  --loc-addr-color: #8C8C8C;
  --loc-dist-display: none;            /* 想显示「距你 xx km」改成 block */

  /* 个人名片 */
  --cc-w: 230px;
  --cc-radius: 10px;
  --cc-avatar-size: 46px;
  --cc-name-color: #1A1A1A;
  --cc-desc-color: #8C8C8C;
  /* 同时覆盖 App 自带变量 */
  --contact-card-bg: #FFFFFF;
  --contact-card-radius: 10px;
  --contact-card-avatar-radius: 50%;
  --contact-card-divider: transparent;
  --contact-card-border: none;
  --contact-card-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
  --contact-card-foot: #9A9A9A;

  /* 文件卡 */
  --file-w: 230px;
  --file-h: 76px;
  --file-radius: 10px;
  --file-icon-img: url("https://i.postimg.cc/Kzs9dz2w/IMG-6037.png");
  --file-icon-w: 39px;
  --file-icon-h: 45px;
  --file-name-color: #1A1A1A;
  --file-meta-color: #9A9A9A;
  --file-status-me: " / 已发送";
  --file-status-them: " / 已接收";
}

/* ◆◆◆ 【01 礼物卡 · Kakao 선물하기】 ◆◆◆ */
/* ═══════════════════════════════════════════════
   卡片 270×463，所有图层叠在卡片自己的背景里（::before 实测不显示）
   绿卡位置：x 12~258，y 18~236（横幅 165 + 商品条 53）
   图层从上到下：
   ⓪ 浅灰遮条（盖住插画伸出绿卡上边、右边的部分）
   ① 四角补片（左上 / 右下斜切 + 右上 / 左下圆角）
   ② 商品条文字  ③ 商品图  ④ 横幅文字  ⑤ 插画
   ⑥ 横幅绿底  ⑦ 商品条白底  ⑧ 左下角图标  ⑨ 下半部分  ⑩ 上半浅灰底
   ═══════════════════════════════════════════════ */

/* 1. 卡片本体 */
div.chat-detail-screen:not(#_k) .msg-gift-card {
  /* ⑨ 下半部分：未收下 = 메시지카드 열기 */
  --gift-bottom: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='270' height='209' viewBox='0 0 270 209'><g font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='14' fill='%23222222'><text x='10' y='42'>💌 함께 온 메시지</text><text x='10' y='64'>&quot;오다 주웠다.&quot;</text></g><rect x='12' y='85' width='246' height='41' rx='8' fill='%23F2F2F2'/><rect x='12' y='131' width='246' height='41' rx='8' fill='%23F2F2F2'/><g font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='14' fill='%23222222' text-anchor='middle'><text x='135' y='110'>주문내역 보기</text><text x='135' y='156'>메시지카드 열기</text></g><text x='38' y='197' font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='11' fill='%23666666'>카카오톡 선물하기</text><path d='M253 188l5 5-5 5' fill='none' stroke='%23BBBBBB' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/></svg>");

  position: relative !important;
  width: 270px !important;
  min-width: 270px !important;
  max-width: 270px !important;
  height: 463px !important;
  min-height: 463px !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 14px !important;
  box-shadow: none !important;
  overflow: hidden !important;
  animation: none !important;
  transform: none !important;
  cursor: pointer !important;
  background-color: #FFFFFF !important;
  background-image:
    /* ⓪a 上方浅灰遮条：插画伸出绿卡顶边的部分 */
    linear-gradient(#F2F2F2, #F2F2F2),
    /* ⓪b 右侧浅灰遮条：插画伸出绿卡右边的部分（含原图白边） */
    linear-gradient(#F2F2F2, #F2F2F2),
    /* ① 四角补片：改斜切大小就改 path 里的 10 */
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='246' height='218' viewBox='0 0 246 218'><path fill='%23F2F2F2' d='M0 0H10L0 10Z M246 208V218H236Z M238 0H246V8A8 8 0 0 0 238 0Z M0 210A8 8 0 0 0 8 218H0Z'/></svg>"),
    /* ② 商品条文字：CU + 礼物名 */
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='246' height='53' viewBox='0 0 246 53'><g font-family='-apple-system,BlinkMacSystemFont,sans-serif'><text x='62' y='22' font-size='12' fill='%23999999'>Lover</text><text x='62' y='41' font-size='12.5' font-weight='600' fill='%23222222'>오늘도 너무 보고 싶어</text></g></svg>"),
    /* ③ 商品图 */
    url("https://i.postimg.cc/FsF6cHpk/IMG-6315.jpg"),
    /* ④ 横幅文字：两行 y 差 28，一起加减就能整体上下挪 */
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='246' height='165' viewBox='0 0 246 165'><g font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='18' font-weight='700' fill='%23FFFFFF'><text x='22' y='34'>오다 주웠다</text><text x='22' y='62'>너 가져</text></g></svg>"),
    /* ⑤ 插画：礼物盒 + 手 */
    url("https://i.postimg.cc/LXXSN3BW/IMG-6313.png"),
    /* ⑥ 横幅绿底 */
    linear-gradient(#02B999, #02B999),
    /* ⑦ 商品条白底 */
    linear-gradient(#FFFFFF, #FFFFFF),
    /* ⑧ 左下角图标 */
    url("https://i.postimg.cc/jjkqV1jp/IMG-6314.png"),
    /* ⑨ 下半部分（跟着收下状态切换） */
    var(--gift-bottom),
    /* ⑩ 上半浅灰底 */
    linear-gradient(#F2F2F2, #F2F2F2) !important;
  background-repeat: no-repeat !important;
  background-position:
    0 0,                               /* ⓪a */
    258px 0,                           /* ⓪b 从绿卡右边缘开始 */
    12px 18px,                         /* ① */
    12px 183px,                        /* ② */
    21px 189px,                        /* ③ */
    12px 18px,                         /* ④ */
    68px 3px,                          /* ⑤ 插画：x 贴右边，y 比绿卡顶边高 15px */
    12px 18px,                         /* ⑥ */
    12px 183px,                        /* ⑦ */
    10px 436px,                        /* ⑧ 图标 */
    0 254px,                           /* ⑨ */
    0 0 !important;                    /* ⑩ */
  background-size:
    100% 18px,                         /* ⓪a */
    12px 183px,                        /* ⓪b */
    246px 218px,                       /* ① */
    246px 53px,                        /* ② */
    44px 42px,                         /* ③ 商品图大小 */
    246px 165px,                       /* ④ */
    204px 165px,                       /* ⑤ 插画，按原图比例 950:770 */
    246px 165px,                       /* ⑥ */
    246px 53px,                        /* ⑦ */
    22px 22px,                         /* ⑧ 图标大小 */
    270px 209px,                       /* ⑨ */
    100% 254px !important;             /* ⑩ */
}

/* 1b. 收下礼物后：第二个按钮换成「선물 받음」 */
/* 拆开后的类名指南里没写，这里先猜几个常见的；不生效就要查元素 */
div.chat-detail-screen:not(#_k) :is(
  .msg-gift-card.is-opened,
  .msg-gift-card.opened,
  .msg-gift-card.gift-opened,
  .msg-gift-card[data-opened="true"],
  .msg-gift-card[class*="opened"]:not([class*="unopened"]),
  .msg-gift-card:has([class*="opened"]:not([class*="unopened"]))
) {
  --gift-bottom: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='270' height='209' viewBox='0 0 270 209'><g font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='14' fill='%23222222'><text x='10' y='42'>💌 함께 온 메시지</text><text x='10' y='64'>&quot;오다 주웠다.&quot;</text></g><rect x='12' y='85' width='246' height='41' rx='8' fill='%23F2F2F2'/><rect x='12' y='131' width='246' height='41' rx='8' fill='%23F2F2F2'/><g font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='14' fill='%23222222' text-anchor='middle'><text x='135' y='110'>주문내역 보기</text><text x='135' y='156'>선물 받음</text></g><text x='38' y='197' font-family='-apple-system,BlinkMacSystemFont,sans-serif' font-size='11' fill='%23666666'>카카오톡 선물하기</text><path d='M253 188l5 5-5 5' fill='none' stroke='%23BBBBBB' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/></svg>");
}

/* 2. 卡片自己的伪元素清掉，免得 App 原装饰压在图层上 */
div.chat-detail-screen:not(#_k) .msg-gift-card::before,
div.chat-detail-screen:not(#_k) .msg-gift-card::after {
  content: none !important;
  display: none !important;
}

/* 3. 原礼物盒：透明铺满整张卡，点击照常拆开 */
div.chat-detail-screen:not(#_k) .msg-gift-card > * {
  position: absolute !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  margin: 0 !important;
  z-index: 2 !important;
  opacity: 0 !important;
  animation: none !important;
}

/* 4. 外层气泡去壳 */
div.chat-detail-screen:not(#_k):not(#_k) .msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-gift-card) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* ◆◆◆ 【02 真实位置】 ◆◆◆ */
/* 微信排版：上文字 + 下地图 */

/* 1. 外层气泡去壳 */
div.chat-detail-screen:not(#_k) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.msg-loc-card) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  overflow: visible !important;
}

/* 2. 卡片本体：白底，flex 列排布 */
div.chat-detail-screen:not(#_k) .msg-loc-card {
  display: flex !important;
  flex-direction: column !important;
  align-items: stretch !important;
  width: var(--loc-w) !important;
  max-width: none !important;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  background: #FFFFFF !important;
  border: none !important;
  border-radius: var(--loc-radius) !important;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08) !important;
  overflow: hidden !important;
}

/* 3. 文字区：排在上面 */
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-info {
  order: 1 !important;
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: flex-start !important;
  justify-content: center !important;
  padding: 8px 12px !important;
  background: transparent !important;
  border: none !important;
}
/* 主名称 */
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-name {
  margin: 0 !important;
  color: var(--loc-name-color) !important;
  font-size: 16px !important;
  font-weight: 500 !important;
  line-height: 1.3 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  width: 100% !important;
  -webkit-font-smoothing: antialiased !important;
}
/* 详细地址 */
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-addr {
  margin: 3px 0 0 !important;
  color: var(--loc-addr-color) !important;
  font-size: 12px !important;
  font-weight: 400 !important;
  line-height: 1.2 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  width: 100% !important;
  -webkit-font-smoothing: antialiased !important;
}
/* 距离 / 大概位置提示 */
div.chat-detail-screen:not(#_k) .msg-loc-card :is(.msg-loc-dist, .msg-loc-approx) {
  display: var(--loc-dist-display) !important;
  margin: 2px 0 0 !important;
  color: var(--loc-addr-color) !important;
  font-size: 10px !important;
  font-weight: 400 !important;
}
div.chat-detail-screen:not(#_k) .msg-loc-card :is(.msg-loc-dist, .msg-loc-approx)::before {
  content: none !important;
}

/* 4. 地图区：排在下面，原生地图隐藏，换成图片 */
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-map {
  order: 2 !important;
  position: relative !important;
  display: block !important;
  flex: none !important;
  width: 100% !important;
  height: var(--loc-map-h) !important;
  min-height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  background: #EEEEEE var(--loc-map-img) center / cover no-repeat !important;
  filter: none !important;
  overflow: hidden !important;
}
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-map > * {
  display: none !important;
}
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-map::before,
div.chat-detail-screen:not(#_k) .msg-loc-card .msg-loc-map::after {
  display: none !important;
}

/* 5. 底栏隐藏 */
div.chat-detail-screen:not(#_k) .msg-loc-card :is(.msg-loc-footer, .msg-loc-footer-text) {
  display: none !important;
}

/* ◆◆◆ 【03 个人名片】 ◆◆◆ */
/* 结构（指南）：.cc-card > .cc-top（.cc-avatar + .cc-name / .cc-sign）+ .cc-foot */

/* 1. 外层气泡去壳 */
div.chat-detail-screen:not(#_k) :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(.cc-card) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  padding: 0 !important;
  overflow: visible !important;
}

/* 2. 卡片本体 */
div.chat-detail-screen:not(#_k) .cc-card {
  width: var(--cc-w) !important;
  min-width: 0 !important;
  max-width: none !important;
  height: auto !important;
  padding: 0 !important;
  box-sizing: border-box !important;
  overflow: hidden !important;
}

/* 3. 上半部：头像 + 名字横排，上下居中 */
div.chat-detail-screen:not(#_k) .cc-card .cc-top {
  position: relative !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;        /* 名字和头像垂直居中 */
  justify-content: flex-start !important;
  gap: 0 !important;
  padding: 12px 14px 14px !important;    /* ← 上 12 / 左 14：头像离卡片边的距离 */
  background: transparent !important;
  border: none !important;
}

/* 头像 */
div.chat-detail-screen:not(#_k) .cc-card .cc-avatar {
  flex: 0 0 var(--cc-avatar-size) !important;
  width: var(--cc-avatar-size) !important;
  height: var(--cc-avatar-size) !important;
  margin: 0 10px 0 0 !important;         /* ← 右边 10px = 头像和名字的距离 */
  align-self: center !important;
}

/* 名字外面如果还包了一层无类名容器：清掉间距，交给 flex 居中 */
div.chat-detail-screen:not(#_k) .cc-card .cc-top > :not(.cc-avatar) {
  position: relative !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  align-self: center !important;
  display: flex !important;
  flex-direction: column !important;
  justify-content: center !important;
  align-items: flex-start !important;
  margin: 0 !important;
  padding: 0 !important;
  text-align: left !important;
}

/* 名字 */
div.chat-detail-screen:not(#_k) .cc-card .cc-name {
  margin: 0 !important;
  padding: 0 !important;
  text-align: left !important;
}
div.chat-detail-screen:not(#_k) .cc-card .cc-name,
div.chat-detail-screen:not(#_k) .cc-card .cc-name * {
  color: var(--cc-name-color) !important;
  -webkit-text-fill-color: var(--cc-name-color) !important;
  font-size: 16px !important;
