}
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-play-btn :is(*, svg, path) {
  display: none !important;
}

/* --- 4. 时长：黑色，推到最右 --- */
div.chat-detail-screen:not(#_k) .msg-bubble-wrapper.msg-bubble-wrapper.msg-bubble-wrapper .voice-msg .voice-duration {
