div.chat-detail-screen:not(#_k):not(#_k) .msg-bubble-wrapper:has(.msg-gift-card, .msg-loc-card, .cc-card, .msg-file-card)::before,
div.chat-detail-screen:not(#_k):not(#_k) .msg-bubble-wrapper:has(.msg-gift-card, .msg-loc-card, .cc-card, .msg-file-card)::after {
