)::before,
div.chat-detail-screen:not(#_k):not(#_k) .msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has(
  .msg-history-card,
  .msg-forum-share-card,
  .ext-share-card,
  .lp-card,
  [class*="card"]
)::after,
div.chat-detail-screen:not(#_k):not(#_k) .msg-bubble-wrapper:has(
  .msg-history-card,
  .msg-forum-share-card,
  .ext-share-card,
  .lp-card,
  [class*="card"]
