  .msg-forum-share-card,
  .ext-share-card,
  .lp-card,
  [class*="card"]
)::after {
  content: none !important;
  display: none !important;
}
/* ◆◆◆◆◆◆◆◆◆◆◆◆ 【19 朋友圈分享卡去气泡】 ◆◆◆◆◆◆◆◆◆◆◆◆ */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me, .bubble-them-custom, .msg-plain-them):has([class*="moment"], [class*="Moment"], [class*="share"], [class*="feed"], [class*="timeline"], [class*="post"]) {
