/* --- 2. AI 方转账 / 红包 / 通话：上面的备注名（样式和 04 一致） --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper.msg-them:is(.is-first, .is-single) :is(.bubble-them-custom, .msg-plain-them):has(:is(.msg-transfer-card, .msg-redpacket-card, .msg-videocall-card))::before {
  content: "구온우" !important;        /* ← 和 04 的备注保持一致 */
  display: block !important;
  position: absolute !important;
  top: -18px !important;
  left: 4px !important;
  right: auto !important;
  width: auto !important;
  height: auto !important;
  background: none !important;
  font-size: 12.5px !important;
  line-height: 15px !important;
  font-weight: 400 !important;
  color: #4A5560 !important;
  -webkit-text-fill-color: #4A5560 !important;
  white-space: nowrap !important;
  pointer-events: none !important;
  z-index: 4 !important;
}
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper.msg-them:is(.is-first, .is-single) :is(.bubble-them-custom, .msg-plain-them):has(:is(.msg-transfer-card, .msg-redpacket-card, .msg-videocall-card)) {
  margin-top: 20px !important;        /* 和 04 的下压距离一致 */
}

/* --- 3. 通话气泡：底色 + padding + Kakao 尾巴 --- */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper.msg-them :is(.bubble-them-custom, .msg-plain-them):has(.msg-videocall-card) {
  background: #FFFFFF !important;
  padding: 6px 12px !important;
