/* 2. 去掉 Kakao 上角尾巴（双方都去） */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper :is(.bubble-them-custom, .msg-plain-them, .bubble-me-custom, .msg-plain-me):has(img[class*="sticker"], [class*="sticker"] img):not(:has(.msg-reply-block))::after {
 content: none !important;
 display: none !important;
}

/* 3. 我方没有备注名，::before 也一起关掉，防止残留装饰 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper :is(.bubble-me-custom, .msg-plain-me):has(img[class*="sticker"], [class*="sticker"] img):not(:has(.msg-reply-block))::before {
 content: none !important;
 display: none !important;
}

/* 4. 装饰层也透明，有的版本底色画在外面这层 */
div.chat-detail-screen:not(#_k):not(#_k):not(#_k) .msg-bubble-wrapper:has(img[class*="sticker"], [class*="sticker"] img):not(:has(.msg-reply-block)) :is(.bubble-deco-me, .bubble-deco-them) {
 background: transparent !important;
 box-shadow: none !important;
 border: none !important;
}

:root {
