    --send-btn-size: 32px;
    --send-btn-radius: 50%;
    --send-btn-shadow: 0 2px 8px rgba(11, 132, 255, 0.35);

    --plus-btn-color: #ffffff;

    --timestamp-color: rgba(255, 255, 255, 0.55);
    --date-divider-bg: rgba(255, 255, 255, 0.12);
    --date-divider-color: rgba(255, 255, 255, 0.6);
}

/* ===== Header - 浮动透明，液态玻璃按钮 ===== */

.chat-detail-screen .chat-header-custom {
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    z-index: 10 !important;
    background: linear-gradient(to bottom, rgba(0,0,0,0.18) 0%, rgba(0,0,0,0.06) 60%, transparent 100%) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-bottom: none !important;
    box-shadow: none !important;
    height: auto !important;
    min-height: 90px !important;
    align-items: flex-start !important;
    padding-top: max(var(--nuo-safe-top), 12px) !important;
