    color: #b2b8c0 !important;
    font-size: 14px !important;
    pointer-events: none !important;
    white-space: nowrap !important;
}
.comment-input-bar .comment-input-row:has(input:not(:placeholder-shown))::after,
.nuo-forum-comment-input .comment-input-row:has(input:not(:placeholder-shown))::after {
    display: none !important;
}
/* ★ 单独放大发送图标 */
.comment-input-bar .comment-input-row > .forum-icon-btn:last-child::before,
.nuo-forum-comment-input .comment-input-row > .forum-icon-btn:last-child::before {
    width: 100px !important;
    height: 100px !important;
}
.comment-input-bar .comment-input-row > .forum-icon-btn:last-child,
.nuo-forum-comment-input .comment-input-row > .forum-icon-btn:last-child {
    width: 60px !important;
    height: 60px !important;
    min-width: 60px !important;
}

data.css:
.vintage-time-widget {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  background: transparent;
  box-sizing: border-box;
  /*⁣‍‌​⁠​‌⁠⁠​‌⁠​‍⁠‍‌​​⁠⁠⁠​​‍‌‍‌⁠​‍‌​⁠‌​​‌‍⁠​‌​‌⁠‌‌⁠⁠​‍​​​​⁠​⁠​‍‌‍‍​‍⁣ 极弱的文字阴影，防止在复杂壁纸上看不清 */
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

/* 顶部：星期与时段 */
.time-period {
  color: #ffffff;
  font-size: 18px; 
  font-family: "PingFang SC", "Helvetica Neue", Helvetica, Arial, sans-serif;
  font-weight: 500;
  letter-spacing: 2px; 

  /* 核心修改：把与下方数字的间距大幅拉开 */
  margin-bottom: 35px; 

  opacity: 0.95;
}

/* 底部：时间数字容器 */
.time-display {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 15px; /* 稍微拉开数字和竖线之间的距离 */
}

/* 具体的数字样式 */
.time-display span {
  color: #ffffff;
  font-family: "Times New Roman", Times, Georgia, serif; 

  /* 核心修改：数字字号从 110px 缩小到 85px */
  font-size: 85px; 

  font-weight: 400; 
  line-height: 1;
  letter-spacing: 3px; /* 数字内部稍微收一点 */
}

/* 中间的竖线分隔符 */
.time-display .separator {
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif; 

  /* 竖线也相应缩小 */
  font-size: 65px; 

  font-weight: 300; 
  opacity: 0.7; 
  transform: translateY(-4px); /* 微调竖线高度，对齐数字 */
}

.profile-widget {
  display: flex;
  justify-content: space-between;
  align-items: center;
  width: 100%;
  height: 100%;
  padding: 5px; 
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Helvetica Neue", sans-serif;
}

.side-column {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 70%; 
}

.left-column { align-items: flex-start; }
.right-column { align-items: flex-end; }

/*⁣‍‌​⁠​‌⁠⁠​‌⁠​‍⁠‍‌​​⁠⁠⁠​​‍‌‍‌⁠​‍‌​⁠‌​​‌‍⁠​‌​‌⁠‌‌⁠⁠​‍​​​​⁠​⁠​‍‌‍‍​‍⁣ 玻璃质感标签（已去白边） */
.glass-tag {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 10px; 

  background: rgba(255, 255, 255, 0.75);
  backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);

  /* 核心修改：删除了 border，去掉了外面的白边 */

  border-radius: 30px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.15);
  white-space: nowrap; 
}

.tag-icon {
  font-size: 13px; 
  color: #333333;
  flex-shrink: 0; 
}

.tag-text {
  font-size: 12px; 
  font-weight: 600;
  color: #333333; 
}

/* ================= 中间头像与文字 ================= */
.center-column {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px; 
  flex-shrink: 0; 
  padding: 0 5px; 
}

.avatar-box {
  width: 95px; 
  height: 95px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.2); 
}

.avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.footer-decor {
  color: #ffffff; 
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 2px;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.8), 0 1px 3px rgba(0, 0, 0, 0.6);
}

.music-profile-widget {
  position: relative;
  width: 100%;
  height: 100%;
  background: transparent;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Helvetica Neue", Helvetica, Arial, sans-serif;
}

.avatar-box {
  position: absolute;
  top: 10%;
  left: 8%;
  /* 修改头像大小 */
  width: 76px;
  height: 76px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.15); 
}

.avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* 右上角波纹字符样式 */
.audio-text {
  position: absolute;
  top: 16%;
  right: 12%;

  /* 修改波纹字符的颜色、大小和粗细 */
  color: #ffffff;
  font-size: 24px;
  font-weight: 900;
  letter-spacing: 2px;
  font-family: "Helvetica Neue", Helvetica, Arial, sans-serif;

  /* 文字阴影，防止在浅色壁纸上隐身 */
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.3);
}

.bottom-text {
  position: absolute;
  bottom: 15%;
  left: 8%;

  /* 修改文字颜色和大小 */
  color: #ffffff;
  font-size: 16px; 
  font-weight: 600;
  letter-spacing: 1px;
  text-shadow: 0 2px 6px rgba(0, 0, 0, 0.3), 0 1px 2px rgba(0, 0, 0, 0.2);
}

custom.css:
.page { position: absolute; inset: 0; color: #fff; font-family: -apple-system, "PingFang SC", sans-serif; }
.bg { position: absolute; inset: 0; background: {{accent}} url("{{portrait}}") center top / cover no-repeat; }
.bg::after { content: ""; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(0,0,0,.4), rgba(0,0,0,0) 30%, rgba(0,0,0,0) 55%, rgba(0,0,0,.6)); }
.clock { position: absolute; left: 24px; top: calc(var(--safe-top, 44px) + 16px); }
.clock b { display: block; font-size: 64px; line-height: 1; letter-spacing: -1px; }
.clock small { display: block; margin-top: 6px; font-size: 14px; opacity: .9; }
.card { position: absolute; left: 20px; right: 20px; bottom: 124px; padding: 12px 16px; border-radius: 16px; background: rgba(255,255,255,.92); color: #333; }
.card em { font-style: normal; font-size: 13px; font-weight: 700; color: {{accent}}; }
.card p { margin: 4px 0 0; font-size: 15px; line-height: 1.5; }
.apps { position: absolute; left: 16px; right: 16px; bottom: 44px; display: flex; gap: 10px; }
.app { flex: 1; padding: 14px 0; border-radius: 16px; text-align: center; font-size: 13px; font-weight: 700; background: rgba(0,0,0,.35); border: 1px solid rgba(255,255,255,.35); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.app.start { background: {{accent}}; border-color: transparent; }
@keyframes rise { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }
@keyframes shine { 0% { background-position: 150% 0; } 60%, 100% { background-position: -50% 0; } }
html.tp-fx:not(.tp-enter) .clock, html.tp-fx:not(.tp-enter) .card, html.tp-fx:not(.tp-enter) .apps { opacity: 0; }
.tp-enter .clock { animation: rise .8s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .card { animation: rise .8s .15s cubic-bezier(.2,.8,.2,1) both; }
.tp-enter .apps { animation: rise .8s .3s cubic-bezier(.2,.8,.2,1) both; }
.app.start { background-image: linear-gradient(110deg, transparent 35%, rgba(255,255,255,.55) 50%, transparent 65%); background-size: 250% 100%; background-repeat: no-repeat; animation: shine 3s ease-in-out infinite; }

value.css:
/*⁣‍‌​⁠​‌⁠⁠​‌⁠​‍⁠‍‌​​⁠⁠⁠​​‍‌‍‌⁠​‍‌​⁠‌​​‌‍⁠​‌​‌⁠‌‌⁠⁠​‍​​​​⁠​⁠​‍‌‍‍​‍⁣ =========================================================
AO3 章节页整合稳定终版
- 针对不支持变量的全屏软件彻底重写固定高度
- 第一行/第二行栏目变宽敞，修复被状态栏遮挡问题
- 单行平均分布按钮 / 无按钮外框
- 标题渐变 / 标题细红线 / 纸张感
========================================================= */

/* ===== 变量 ===== */
:root {
--ao3-red: #900;
--ao3-red-dark: #7a0000;
--ao3-bg: #ece4da;
--ao3-paper: #fffdfa;
--ao3-paper-soft: #fcf8f4;
--ao3-paper-2: #f4ece4;
--ao3-text: #1f1f1f;
--ao3-text-2: #2b2b2b;
--ao3-soft: #555;
--ao3-line: #d8c8bc;
--ao3-line-dark: #c9b7aa;
--ao3-quote: #f3e7dc;
--ao3-link: #900;
--ao3-link-hover: #b30000;
}

/* ===== 全局 ===== */
#this-moment-screen {
background: var(--ao3-bg) !important;
color: var(--ao3-text) !important;
font-family:
Georgia,
"Noto Sans CJK SC",
"Noto Sans SC",
"Source Han Sans SC",
"PingFang SC",
"Hiragino Sans GB",
"Microsoft YaHei",
sans-serif !important;
font-synthesis: none !important;
}

.tm-bg-overlay {
background:
linear-gradient(to bottom, rgba(255,255,255,.16), rgba(255,255,255,.08)),
var(--ao3-bg) !important;
}

.tm-bg-image {
display: none !important;
}

/* ===== 顶栏 ===== */
.tm-header {
position: relative !important;
display: grid !important;
grid-template-columns: auto 1fr auto !important;
/* 👇 两栏的高度变大了：54px 和 40px */
grid-template-rows: 54px 40px !important;
grid-template-areas:
"left left right"
"chars chars chars" !important;
column-gap: 8px !important;
row-gap: 0 !important;
align-items: center !important;
/* 👇 给顶部状态栏留出 35px 的死空间 */
padding: 35px 0 0 0 !important;
/* 35 + 54 + 40 = 129px */
min-height: 129px !important;
border-bottom: none !important;
box-sizing: border-box !important;
overflow: hidden !important;
z-index: 30 !important;
background: linear-gradient(
to bottom,
#fdfbf7 0,
#fdfbf7 89px,
var(--ao3-red) 89px,
var(--ao3-red) 100%
) !important;
box-shadow: inset 0 2px 0 #900 !important;
}

.tm-header::after {
grid-area: left !important;
content: "Archive of Our Own" !important;
color: var(--ao3-red) !important;
font-weight: 700 !important;
font-size: 18px !important;
font-family: Garamond, Georgia, serif !important;
white-space: nowrap !important;
background-image: url('https://i.postimg.cc/9fhMD3Zx/Screenshot-20260409-121451-com-xingin-xhs-Note-Detail-Activity-edit-3579091065401294.jpg') !important;
background-size: 28px 28px !important;
background-repeat: no-repeat !important;
background-position: left center !important;
padding-left: 36px !important;
line-height: 1 !important;
height: 54px !important;
display: flex !important;
align-items: center !important;
justify-self: start !important;
margin-left: 12px !important;
align-self: center !important;
}

.tm-header::before {
display: none !important;
}

.tm-header-right {
grid-area: right !important;
display: flex !important;
align-items: center !important;
justify-content: flex-end !important;
gap: 12px !important;
height: 54px !important;
padding: 0 12px !important;
background: transparent !important;
position: relative !important;
z-index: 2 !important;
}

.tm-header-right .tm-btn-icon {
display: flex !important;
align-items: center !important;
justify-content: center !important;
background: transparent !important;
border: none !important;
color: var(--ao3-red) !important;
font-size: 16px !important;
font-weight: 700 !important;
padding: 0 !important;
min-width: auto !important;
}

.tm-header-right .tm-btn-icon svg {
display: none !important;
}

.tm-header-right .tm-btn-icon:first-child::before {
content: "Browse" !important;
color: var(--ao3-red) !important;
font-size: 16px !important;
font-weight: 700 !important;
}

.tm-header-right .tm-btn-icon:nth-child(2):before {
content: "About" !important;
color: var(--ao3-red) !important;
font-size: 16px !important;
font-weight: 700 !important;
}

/* 角色区 */
.tm-header-center {
grid-area: chars !important;
display: flex !important;
align-items: center !important;
justify-content: center !important;
gap: 8px !important;
width: 100% !important;
min-width: 0 !important;
margin: 0 !important;
padding: 0 56px !important;
height: 40px !important;
box-sizing: border-box !important;
background: transparent !important;
position: relative !important;
z-index: 1 !important;
}

.tm-header-center .tm-header-name {
color: #fff !important;
font-size: 14px !important;
font-weight: 700 !important;
text-align: center !important;
white-space: nowrap !important;
overflow: hidden !important;
text-overflow: ellipsis !important;
max-width: min(60vw, 320px) !important;
}

.tm-header-center .tm-header-avatar {
width: 24px !important;
height: 24px !important;
border: 1px solid #fff !important;
flex: 0 0 24px !important;
}

.tm-top-vs {
color: rgba(255,255,255,.82) !important;
}

/* 返回键 */
.tm-header>.tm-btn-icon:first-child {
position: absolute !important;
left: 12px !important;
top: 109px !important;
transform: translateY(-50%) !important;
width: 36px !important;
height: 28px !important;
display: flex !important;
align-items: center !important;
justify-content: center !important;
background: transparent !important;
border: none !important;
color: var(--ao3-red) !important;
fill: var(--ao3-red) !important;
z-index: 3 !important;
}

.tm-header>.tm-btn-icon:first-child svg {
color: var(--ao3-red) !important;
fill: var(--ao3-red) !important;
}

/* ===== 故事区 ===== */
.tm-story {
background: transparent !important;
padding: 18px 14px 28px !important;
box-sizing: border-box !important;
}

.tm-para {
width: min(100%, 860px) !important;
margin: 0 auto 2.1em auto !important;
padding: 0 !important;
box-sizing: border-box !important;
}

.tm-para-char,
.tm-para-user {
position: relative !important;
overflow: hidden !important;
background: var(--ao3-paper) !important;
border: 1px solid var(--ao3-line) !important;
border-radius: 0 !important;
box-shadow:
0 1px 0 rgba(120, 80, 60, 0.04),
0 3px 10px rgba(120, 80, 60, 0.06) !important;
padding: 1.1em 1.2em 1.2em !important;
margin: 0 !important;
}

.tm-para-user {
background: var(--ao3-paper-soft) !important;
border-color: #d9c9bd !important;
}

.tm-para-char::before,
.tm-para-user::before {
content: "" !important;
position: absolute !important;
left: 0 !important;
right: 0 !important;
top: 0 !important;
height: 18px !important;
background: linear-gradient(
to bottom,
rgba(255,255,255,0.28),
rgba(255,255,255,0)
) !important;
pointer-events: none !important;
}

/* ===== 章节头 ===== */
.tc-header {
position: relative !important;
background: transparent !important;
border-bottom: none !important;
padding: 0 0 .9em 0 !important;
margin: 0 0 1.1em 0 !important;
}

.tc-header::after {
content: "" !important;
display: block !important;
width: 100% !important;
height: 1px !important;
margin-top: 10px !important;
background: linear-gradient(
to right,
transparent 0%,
#900 18%,
#900 82%,
transparent 100%
) !important;
opacity: 0.75 !important;
}

.tc-header-user {
display: none !important;
}

.tc-avatar-frame {
border: 1px solid #c8b9ae !important;
border-radius: 0 !important;
box-shadow: none !important;
width: 62px !important;
height: 62px !important;
}

.tc-avatar-badge {
color: var(--ao3-soft) !important;
font-size: 11px !important;
}

/* ❤️❤️❤️ 标题位置：改这里 ❤️❤️❤️ */
.tc-meta-title {
font-size: 0 !important;
}

.tc-meta-title::after {
content: "The Hour We Kept" !important;
display: block !important;
background: linear-gradient(180deg, #a10000 0%, #900 45%, #7a0000 100%) !important;
-webkit-background-clip: text !important;
background-clip: text !important;
-webkit-text-fill-color: transparent !important;
text-shadow: 0 1px 0 rgba(255,255,255,0.35) !important;
font-family: Georgia, "Times New Roman", serif !important;
font-size: 1.68rem !important;
line-height: 1.24 !important;
font-weight: 400 !important;
letter-spacing: 0.2px !important;
}

/* ❤️❤️❤️ 作者位置：改这里 ❤️❤️❤️ */
.tc-meta-subtitle {
min-height: 18px !important;
}

.tc-meta-subtitle::before {
content: "by us" !important;
display: inline-block !important;
color: var(--ao3-red-dark) !important;
font-family: Georgia, "Times New Roman", serif !important;
font-size: .98rem !important;
font-style: italic !important;
}

/* stats */
.tc-meta-stats {
gap: 6px !important;
flex-wrap: wrap !important;
}

.tc-stat {
background: var(--ao3-paper-2) !important;
color: var(--ao3-red) !important;
border: 1px solid #d8c4b8 !important;
border-radius: 0 !important;
font-size: 12px !important;
padding: 2px 8px !important;
}

.tc-stat[data-label="page"] {
font-size: 12px !important;
color: var(--ao3-red) !important;
}

.tc-stat[data-label="page"]::before {
content: "Chapter " !important;
color: var(--ao3-red) !important;
}

.tc-divider-text::before {
content: "" !important;
}

/* ===== 正文 ===== */
.tm-body-char,
.tm-body-user {
width: 100% !important;
max-width: 100% !important;
margin: 0 auto !important;
color: var(--ao3-text) !important;
background: transparent !important;
font-family:
Georgia,
"Noto Sans CJK SC",
"Noto Sans SC",
"Source Han Sans SC",
"PingFang SC",
"Hiragino Sans GB",
"Microsoft YaHei",
sans-serif !important;
font-size: 17px !important;
line-height: 1.82 !important;
font-weight: 400 !important;
letter-spacing: 0 !important;
text-align: left !important;
box-sizing: border-box !important;
}

.tm-body-char .tm-para-block,
.tm-body-user .tm-para-block {
margin: 0 0 1em 0 !important;
padding: 0 !important;
text-indent: 2em !important;
}

.tm-body-char .tm-para-block:first-child,
.tm-body-user .tm-para-block:first-child {
margin-top: 0 !important;
}

.tm-body-char {
color: #1e1e1e !important;
}

.tm-body-user {
color: #2b2b2b !important;
}

/* ===== 文本格式增强 ===== */
.tm-body-char *,
.tm-body-user * {
max-width: 100%;
}

.tm-bold,
.tm-body-char strong,
.tm-body-user strong,
.tm-body-char b,
.tm-body-user b {
font-weight: 700 !important;
color: #7a0000 !important;
background: rgba(153, 0, 0, 0.06) !important;
padding: 0 .08em !important;
}

.tm-action,
.tm-body-char em,
.tm-body-user em,
.tm-body-char i,
.tm-body-user i {
font-style: italic !important;
color: #4a3b36 !important;
}

.tm-del,
.tm-body-char del,
.tm-body-user del,
.tm-body-char s,
.tm-body-user s {
color: #777 !important;
text-decoration: line-through !important;
text-decoration-thickness: 1px !important;
opacity: .92 !important;
}

.tm-body-char u,
.tm-body-user u,
.tm-body-char ins,
.tm-body-user ins,
.tm-body-char .tm-underline,
.tm-body-user .tm-underline {
text-decoration-line: underline !important;
text-decoration-style: wavy !important;
text-decoration-color: #b30000 !important;
text-decoration-thickness: 1.5px !important;
text-underline-offset: 2px !important;
}

.tm-body-char mark,
.tm-body-user mark,
.tm-body-char .tm-highlight,
.tm-body-user .tm-highlight {
background: #f7e3cf !important;
color: #7a0000 !important;
padding: 0 .12em !important;
}

.tm-body-char big,
.tm-body-user big,
.tm-body-char .tm-large,
.tm-body-user .tm-large {
font-size: 1.18em !important;
line-height: 1.65 !important;
}

.tm-body-char small,
.tm-body-user small,
.tm-body-char .tm-small,
.tm-body-user .tm-small {
font-size: .88em !important;
color: #666 !important;
}

.tm-body-char [style*="color:"],
.tm-body-user [style*="color:"] {
font-weight: 600 !important;
}

.tm-body-char a,
.tm-body-user a {
color: var(--ao3-link) !important;
text-decoration: underline !important;
}

.tm-body-char a:hover,
.tm-body-user a:hover {
color: var(--ao3-link-hover) !important;
}

.tm-quote-block {
