/* =========================================================
跟随系统上传字体 · 最终合并版
========================================================= */

/* 页面根字体先继承系统 */
#this-moment-screen {
font-family: inherit !important;
}

/* 正文区全部跟系统字体 */
.tm-body-char,
.tm-body-user,
.tm-body-char .tm-para-block,
.tm-body-user .tm-para-block,
.tm-body-char *,
.tm-body-user *,
.tm-quote-block,
.tm-quote-block * {
font-family: inherit !important;
}

/* 输入区、建议区、加载文案跟系统字体 */
.tm-input,
.tm-suggestion-text,
.tm-suggestion-direction,
.tm-suggestion-reroll,
.tm-loading-text,
.tm-loading-text::before,
.tm-compose-row::before {
font-family: inherit !important;
}

/* 标题和作者也尝试跟系统字体 */
.tc-meta-title,
.tc-meta-title::after,
.tc-meta-subtitle,
.tc-meta-subtitle::before {
font-family: inherit !important;
}

/* 顶栏角色名也跟系统字体 */
.tm-header-center,
.tm-header-center .tm-header-name,
.tm-header-center .tm-header-name * {
font-family: inherit !important;
}

/* 底栏按钮英文伪元素也跟系统字体 */
.tm-compose-toolbar>.tm-regen-btn:nth-of-type(1)::before,
.tm-compose-toolbar>.tm-regen-btn:nth-of-type(2)::before,
.tm-compose-toolbar>.tm-regen-btn:nth-of-type(3)::before,
.tm-compose-toolbar>.tm-regen-btn:nth-of-type(4)::before,
.tm-compose-toolbar>.tm-regen-btn:nth-of-type(5)::before,
.tm-compose-toolbar>.tm-suggestions-btn::before,
.tm-send-btn::before,
.tm-header-right .tm-btn-icon:first-child::before,
.tm-header-right .tm-btn-icon:nth-child(2)::before {
font-family: inherit !important;
}

/*⁣‍‌​⁠​‌⁠⁠​‌⁠​‍⁠‍‌​​⁠⁠⁠​​‍‌‍‌⁠​‍‌​⁠‌​​‌‍⁠​‌​‌⁠‌‌⁠⁠​‍​​​​⁠​⁠​‍‌‍‍​‍⁣ 简约线下聊天：宽屏中轴 / 小方头像 / 思维链标记置于头像下方 */

:root {
  --minimal-content-width: 860px;
  --minimal-avatar-size: 46px;
  --minimal-avatar-gap: 14px;
  --minimal-text: #303633;
  --minimal-muted: #9aa19b;
  --minimal-line: rgba(55, 70, 60, 0.12);
  --minimal-chip-bg: rgba(255, 255, 255, 0.72);

  /* 官方框架 token：多人面板 / 提示卡 / 模式切换自动跟随主题 */
  --tm-fg: var(--minimal-text);
  --tm-fg-muted: var(--minimal-muted);
  --tm-border: var(--minimal-line);
  --tm-bg-soft: var(--minimal-chip-bg);
}

/* 消息流：不贴满屏，统一收进宽屏中轴 */
.tm-story {
  width: 100% !important;
  max-width: var(--minimal-content-width) !important;
  margin-inline: auto !important;
  padding-inline: 28px !important;
  box-sizing: border-box !important;
}

.tm-story > .tm-para {
  width: 100% !important;
  max-width: 760px !important;
  margin-inline: auto !important;
  box-sizing: border-box !important;
}

/* 角色 / 用户消息统一成同一条中轴，不做左右气泡 */
.tm-para-char,
.tm-para-user {
  width: 100% !important;
  max-width: 760px !important;
  margin-inline: auto !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 14px 0 !important;
  box-sizing: border-box !important;
  position: relative !important;
}

/* 去掉头像下方的角色名；用户消息保留 badge，把它移到头像旁作为名字位 */
.tc-avatar-badge {
  display: none !important;
}

.tc-avatar-badge-user {
  display: block !important;
  margin: 0 !important;
  padding: 1px 0 0 !important;
  color: var(--minimal-text) !important;
  font-size: 13px !important;
  line-height: 1.35 !important;
  font-weight: 650 !important;
  text-align: left !important;
}

/* 用户 header 补齐与 char 相同的三元素信息层 */
.tc-header-user {
  display: flex !important;
  align-items: flex-start !important;
  position: relative !important;
}

.tc-header-user .tc-avatar-area,
.tc-header-user .tc-avatar-frame-user {
  flex: 0 0 var(--minimal-avatar-size) !important;
}

/* 用户 header：官方 -user 骨架（2026-10），三元素与角色侧一致 */
.tc-header-user .tc-avatar-badge-user {
  display: none !important;
}

.tc-meta-area-user {
  display: flex !important;
  flex-direction: column !important;
  flex: 1 1 auto !important;
  min-width: 0 !important;
  padding-top: 1px !important;
}

.tc-meta-title-user {
  font-size: 13px !important;
  line-height: 1.35 !important;
  color: var(--minimal-text) !important;
  font-weight: 650 !important;
}

.tc-meta-subtitle-user,
.tc-meta-extra-1-user,
.tc-meta-extra-2-user,
.tc-meta-stats-user {
  font-size: 10px !important;
  line-height: 1.4 !important;
  color: var(--minimal-muted) !important;
}

.tc-meta-stats-user {
  display: flex !important;
  gap: 8px !important;
  margin-top: 2px !important;
}

/* 头像缩小为规整方形 */
.tc-header-main,
.tc-header-user {
  align-items: flex-start !important;
  gap: var(--minimal-avatar-gap) !important;
}

.tc-avatar-frame,
.tc-avatar-frame-user {
  width: var(--minimal-avatar-size) !important;
  height: var(--minimal-avatar-size) !important;
  min-width: var(--minimal-avatar-size) !important;
  min-height: var(--minimal-avatar-size) !important;
  border-radius: 7px !important;
  padding: 0 !important;
  border: 1px solid var(--minimal-line) !important;
  box-shadow: none !important;
  overflow: hidden !important;
}

.tc-avatar-img,
.tc-avatar-frame-user img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  border-radius: 6px !important;
}

/* 头像旁三元素信息：名字 / 身份 / 时间保持一行 */
.tc-meta-area {
  min-width: 0 !important;
  flex: 1 1 auto !important;
  padding-top: 1px !important;
}

.tc-meta-title {
  font-size: 13px !important;
  line-height: 1.35 !important;
  color: var(--minimal-text) !important;
  font-weight: 650 !important;
}

.tc-meta-subtitle,
.tc-meta-extra-1,
.tc-meta-extra-2,
.tc-meta-stats {
  font-size: 10px !important;
  line-height: 1.4 !important;
  color: var(--minimal-muted) !important;
}

.tc-meta-stats {
  gap: 8px !important;
  margin-top: 2px !important;
}

.tc-stat {
  padding: 0 !important;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  color: var(--minimal-muted) !important;
}

/* 正文占满消息宽度，不再留下头像宽度的左侧空档 */
.tm-body-char,
.tm-body-user {
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  margin: 8px 0 0 !important;
  padding: 0 !important;
  color: var(--minimal-text) !important;
  font-size: 14px !important;
