  opacity: 0 !important;
  background-image: none !important;
  filter: none !important;
}

/* 清掉遮罩伪元素，避免透明白层叠在正文上 */
.tm-bg-overlay::before,
.tm-bg-overlay::after,
.tm-bg-container::before,
.tm-bg-container::after {
