  /* ---- 14.9 小弹窗：整本酒馆进阶 / 移至分类 / 复制移动词条 ---- */
  .wb-catpick-overlay {
    background: rgba(0, 0, 0, .6) !important;
  }
  .wb-catpick-modal {
    background: #1c1c1e !important;
    color: #fff !important;
    box-shadow: 0 12px 40px rgba(0, 0, 0, .6) !important;
