  background: transparent !important;
}
.wb-book-modal:has(.wb-ctl-edit.editing) .wb-search-bar {
  margin: 2px 0 0 !important;
}

/* ---- 8.1 顶部工具：添加新词条 / 全书优先级 / 批量按钮 ---- */
.wb-entries-list > div:has(> .wb-add-entry-btn) {
  gap: 10px !important;
  margin: 0 !important;
  align-items: stretch !important;
}
.wb-add-entry-btn {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 6px !important;
  height: 46px !important;
  margin: 0 !important;
  padding: 0 14px !important;
  border: 0 !important;
  border-radius: 12px !important;
  background: #fff !important;
  box-shadow: none !important;
  color: #007aff !important;
  font-family: -apple-system, "PingFang SC", sans-serif !important;
  font-size: 16px !important;
  font-weight: 500 !important;
  letter-spacing: 0 !important;
}
.wb-add-entry-btn svg {
  width: 18px !important;
  height: 18px !important;
}
.wb-entries-list > div:has(> .wb-add-entry-btn) > .wb-control-item {
  height: 46px !important;
  box-sizing: border-box !important;
  padding: 0 12px !important;
  border-radius: 12px !important;
