/* =========================================================
   14. 夜间模式：跟随手机系统的深色模式自动切换
   白底 → 黑底，黑字 → 白字，卡片用 iOS 深灰
   ========================================================= */
@media (prefers-color-scheme: dark) {

  /* ---- 14.1 画面底色 ---- */
