  /* ---- 14.7 打开的书：封面 / 词条页 ---- */
  .wb-modal-overlay,
  .wb-book-modal,
  .wb-front-cover,
  .wb-right-page {
    background: #000 !important;
  }
  .wb-cover-title {
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .wb-cover-open-hint {
