  }
  .wb-tab.active {
    background: #636366 !important;
    box-shadow: 0 2px 8px rgba(0, 0, 0, .3) !important;
  }
  .wb-search-bar button,
  .wb-search-bar [class*="sort"] {
    background: rgba(118, 118, 128, .24) !important;
    color: #0a84ff !important;
    -webkit-text-fill-color: #0a84ff !important;
  }
  .wb-search-bar button svg,
  .wb-search-bar [class*="sort"] svg {
    color: #0a84ff !important;
  }

  /* 小纸：深灰纸 + 亮一点的细边和折角 */
  .wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry-content {
    background: linear-gradient(225deg, transparent 12px, #1c1c1e 12px) !important;
    filter: drop-shadow(0 0 .6px rgba(255, 255, 255, .5));
