  .wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry:has(.wb-entry-content:not(.wb-entry-content-collapsed)) .wb-entry-content,
  .wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry:not(:has(.wb-entry-expand-btn)) .wb-entry-content {
    background: linear-gradient(225deg, transparent 22px, #1c1c1e 22px) !important;
    color: #f2f2f7 !important;
  }
  .wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry:has(.wb-entry-content:not(.wb-entry-content-collapsed)) .wb-entry-keywords,
  .wb-book-modal:not(:has(.wb-ctl-edit.editing)) .wb-entry:not(:has(.wb-entry-expand-btn)) .wb-entry-keywords {
