  .wb-batch-toolbar button {
    background: rgba(118, 118, 128, .24) !important;
    color: #0a84ff !important;
  }
  .wb-book-modal:has(.wb-ctl-edit.editing) .wb-entry {
    background: #1c1c1e !important;
  }
