  .wb-book-modal:has(.wb-ctl-edit.editing) .wb-entry > div > div:first-child > button:first-child {
    color: #48484a !important;
  }
  .wb-entry-fold-btn {
    background: rgba(118, 118, 128, .24) !important;
    color: #0a84ff !important;
  }
  .wb-entry-grip {
    color: #48484a !important;
  }
  .wb-entry-input {
    color: #fff !important;
  }
  .wb-book-modal:has(.wb-ctl-edit.editing) .wb-entry > div > input.wb-entry-input {
    color: #ebebf5 !important;
