      radial-gradient(circle, #fff 12.5px, rgba(0, 0, 0, .3) 13px, transparent 14px) 20px 0 / 31px 31px no-repeat,
      #30d158 !important;
  }

  /* 封面编辑输入框 */
  .wb-cover-title-input,
  .wb-cover-description-input {
    background: #1c1c1e !important;
    color: #fff !important;
  }

  /* 设定页（编辑） */
  .wb-settings-section {
    background: #1c1c1e !important;
  }
  .wb-settings-row-label,
  .wb-form-label,
  .wb-settings-section .wb-form-label,
  .wb-settings-section [class*="label"]:not(.wb-toggle-wrapper):not(.wb-toggle-switch) {
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .wb-settings-section > :first-child,
  .wb-settings-section > :first-child * {
    color: #8d8d93 !important;
    -webkit-text-fill-color: #8d8d93 !important;
  }
  .wb-form-input,
  .wb-settings-section input,
  .wb-settings-section textarea {
    background: #2c2c2e !important;
    color: #fff !important;
  }
  .wb-settings-section button:not(.wb-mode-btn),
  .wb-settings-section [class*="upload"],
  .wb-settings-section [class*="picker"],
  .wb-settings-section [class*="file"] {
    background: #2c2c2e !important;
    color: #8d8d93 !important;
    -webkit-text-fill-color: #8d8d93 !important;
  }
  .wb-settings-section [class*="delete"],
  .wb-settings-section [class*="remove"],
  .wb-settings-section [class*="clear"],
  .wb-settings-section button:has(.lucide-trash2),
  .wb-settings-section button:has(.lucide-trash-2) {
    background: rgba(255, 69, 58, .18) !important;
    color: #ff453a !important;
    -webkit-text-fill-color: #ff453a !important;
  }
  .wb-settings-section select {
    background-color: #2c2c2e !important;
    color: #fff !important;
  }

  /* 放大编辑框 */
  .wb-expand-overlay {
    background: rgba(0, 0, 0, .6) !important;
  }
  .wb-expand-modal,
  .wb-expand-textarea {
    background: #1c1c1e !important;
    color: #f2f2f7 !important;
  }
  .wb-expand-modal-header {
    border-bottom-color: rgba(84, 84, 88, .65) !important;
  }
  .wb-expand-modal-title {
    color: #fff !important;
  }
  .wb-expand-modal-close {
    background: rgba(118, 118, 128, .24) !important;
    color: #ebebf5 !important;
  }

  /* ---- 14.9 小弹窗：整本酒馆进阶 / 移至分类 / 复制移动词条 ---- */
  .wb-catpick-overlay {
    background: rgba(0, 0, 0, .6) !important;
  }
  .wb-catpick-modal {
    background: #1c1c1e !important;
    color: #fff !important;
