  }
  .wb-catpick-close {
    background: rgba(118, 118, 128, .24) !important;
    color: #ebebf5 !important;
  }
  .wb-badv-row,
  .wb-badv-row.is-on {
    background: #2c2c2e !important;
  }
  .wb-badv-row + .wb-badv-row {
    box-shadow: inset 0 .5px 0 rgba(84, 84, 88, .65) !important;
  }
  .wb-badv-apply input[type="checkbox"] {
    background: transparent !important;
    border-color: #636366 !important;
  }
  .wb-badv-apply input[type="checkbox"]:checked {
    border-color: #0a84ff !important;
    background-color: #0a84ff !important;
  }
  .wb-badv-input,
  .wb-badv-select {
    background-color: #3a3a3c !important;
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .wb-badv-input::placeholder {
    color: #636366 !important;
    -webkit-text-fill-color: #636366 !important;
  }
  .wb-catpick-modal .wb-select-btn {
    background: rgba(118, 118, 128, .24) !important;
    color: #0a84ff !important;
    -webkit-text-fill-color: #0a84ff !important;
  }
  .wb-catpick-modal .wb-select-btn.primary {
    background: #0a84ff !important;
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .wb-catpick-modal .wb-select-btn.primary:disabled {
    background: rgba(10, 132, 255, .35) !important;
  }
  .wb-catpick-chip,
  .wb-etransfer-item {
    background: #2c2c2e !important;
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .wb-catpick-chip.active,
  .wb-etransfer-item.active {
    background: #0a84ff !important;
  }

  /* ---- 14.10 新建世界书弹窗 ---- */
  .wb-modal-backdrop {
    background: rgba(0, 0, 0, .6) !important;
  }
  .wb-new-modal {
    background: #1c1c1e !important;
    color: #fff !important;
    box-shadow: 0 14px 44px rgba(0, 0, 0, .6) !important;
  }
  .wb-modal-close {
    background: rgba(118, 118, 128, .24) !important;
    color: #ebebf5 !important;
  }
  .wb-new-modal-title {
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .wb-new-modal .wb-form-label {
    color: #8d8d93 !important;
    -webkit-text-fill-color: #8d8d93 !important;
  }
  .wb-new-modal .wb-form-input {
    background: #2c2c2e !important;
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
  }
  .wb-new-modal .wb-form-input::placeholder {
    color: #636366 !important;
    -webkit-text-fill-color: #636366 !important;
  }
  .wb-new-modal .wb-form-input:focus {
    background: #3a3a3c !important;
    box-shadow: 0 0 0 2px rgba(10, 132, 255, .5) !important;
  }
  .wb-submit-btn {
    background: #0a84ff !important;
  }
  .wb-submit-btn:active {
    background: #0070e0 !important;
  }
}

